import json, os, glob

# Fix all OpenVLA checkpoint preprocessor configs to use local modules
for ckpt_dir in glob.glob('/root/autodl-tmp/vla-ssd/checkpoints/openvla-*'):
    pp = os.path.join(ckpt_dir, 'preprocessor_config.json')
    if os.path.exists(pp):
        with open(pp) as f:
            cfg = json.load(f)
        if 'auto_map' in cfg:
            changed = False
            for k, v in cfg['auto_map'].items():
                if '--' in v:
                    cfg['auto_map'][k] = v.split('--', 1)[1]
                    changed = True
            if changed:
                with open(pp, 'w') as f:
                    json.dump(cfg, f, indent=2)
                    f.write('\n')
                print(f'Fixed: {pp}')
                print(f'  auto_map: {cfg[\"auto_map\"]}')
            else:
                print(f'OK (no change): {pp}')

# Also check config.json auto_map
for ckpt_dir in glob.glob('/root/autodl-tmp/vla-ssd/checkpoints/openvla-*'):
    cfg_path = os.path.join(ckpt_dir, 'config.json')
    if os.path.exists(cfg_path):
        with open(cfg_path) as f:
            cfg = json.load(f)
        if 'auto_map' in cfg:
            changed = False
            for k, v in cfg['auto_map'].items():
                if '--' in v:
                    cfg['auto_map'][k] = v.split('--', 1)[1]
                    changed = True
            if changed:
                with open(cfg_path, 'w') as f:
                    json.dump(cfg, f, indent=2)
                    f.write('\n')
                print(f'Fixed config.json: {cfg_path}')
            else:
                print(f'OK config.json: {cfg_path}')
